        base_loads = [route_load(r) for r in routes]

        # Inter-route relocate
        for i in range(len(routes)):
            if changed:
                break
            for idx in range(len(routes[i])):
                c = routes[i][idx]
                dc_remove = route_delta_remove(routes[i], idx)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if base_loads[j] + demand(c) > capacity:
                        continue
                    pos, ins_delta = best_insertion_position(routes[j], c)
                    gain = dc_remove - ins_delta
                    if gain > 1e-12:
                        routes[j].insert(pos, c)
                        routes[i].pop(idx)
                        if not routes[i]:
                            routes.pop(i)
                        changed = True
                        break
                if changed:
                    break

        # Intra-route relocate for order improvement
        if not changed:
            for r in routes:
                best_move = None
                best_gain = 0
                for i in range(len(r)):
                    c = r[i]
                    rem = route_delta_remove(r, i)
                    tmp = r[:i] + r[i + 1:]
                    for pos in range(len(tmp) + 1):
                        prev = depot if pos == 0 else tmp[pos - 1]
                        nxt = depot if pos == len(tmp) else tmp[pos]
                        ins = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                        gain = rem - ins
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = (i, pos)
                if best_move is not None:
                    i, pos = best_move
                    c = r.pop(i)
                    if pos > i:
                        pos -= 1
                    r.insert(pos, c)
                    changed = True
